/*
 * Customer churn KPI dashboard - rendering and interactivity.
 * Data: window.EDVYRO_DATA (dashboard/data.js, generated by analysis/kpi_calculations.py)
 * Maths: window.EdvyroMetrics (dashboard/metrics.js, tested against Python)
 * Charts: Chart.js 4.4.1
 */
(function () {
  "use strict";

  const M = window.EdvyroMetrics;
  const ROWS = window.EDVYRO_DATA.rows;
  const TOTAL = ROWS.length;
  const TABS = ["overview", "churn", "revenue", "segments", "insights"];
  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  const FILTERS = [
    { field: "ContractType", order: "ContractOrder", id: "f-contract" },
    { field: "TenureGroup", order: "TenureGroupOrder", id: "f-tenure" },
    { field: "PaymentMethod", order: null, id: "f-payment" },
    { field: "ChurnStatus", order: null, id: "f-status" },
  ];

  const SEGMENT_ORDER = {
    ContractType: "ContractOrder",
    TenureGroup: "TenureGroupOrder",
    PaymentMethod: null,
    SubscriptionType: "MonthlyCharges",
    SupportTicketBand: "SupportTicketBandOrder",
    AgeGroup: "AgeGroupOrder",
    TotalChargesBand: "TotalChargesBandOrder",
    Gender: null,
  };

  const FIELD_LABELS = {
    ContractType: "Contract type",
    TenureGroup: "Tenure group",
    PaymentMethod: "Payment method",
    SubscriptionType: "Plan",
    SupportTicketBand: "Support tickets",
    AgeGroup: "Age group",
    TotalChargesBand: "Lifetime charges (₹)",
    Gender: "Gender",
  };

  const state = {
    filters: { ContractType: "All", TenureGroup: "All", PaymentMethod: "All", ChurnStatus: "All" },
    tab: "overview",
    segmentDim: "ContractType",
    tableView: new Set(),
  };
  const charts = {};

  /* ---------- formatting ---------- */

  const inr = new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const inrWhole = new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 0 });
  const fmt = {
    int: (v) => (v === null || v === undefined ? "–" : String(v)),
    pct: (v) => (v === null || v === undefined ? "–" : `${v.toFixed(1)}%`),
    money: (v) => (v === null || v === undefined ? "–" : inr.format(v)),
    dec1: (v) => (v === null || v === undefined ? "–" : v.toFixed(1)),
  };

  function listNames(items) {
    if (items.length <= 1) return items.join("");
    return `${items.slice(0, -1).join(", ")} and ${items[items.length - 1]}`;
  }

  /* ---------- theme tokens (read live so light/dark switches repaint charts) ---------- */

  function token(name) {
    return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  }

  function palette() {
    return {
      retained: token("--retained"),
      churned: token("--churned"),
      ink: token("--ink"),
      ink2: token("--ink-2"),
      muted: token("--muted"),
      line: token("--line"),
      baseline: token("--baseline"),
      surface: token("--surface"),
      font: token("--font-ui") || "system-ui, sans-serif",
    };
  }

  function luminance(hex) {
    const n = parseInt(hex.replace("#", ""), 16);
    const channel = (c) => {
      const s = c / 255;
      return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
    };
    return 0.2126 * channel((n >> 16) & 255) + 0.7152 * channel((n >> 8) & 255) + 0.0722 * channel(n & 255);
  }

  // Pick whichever of the two inks has the higher contrast on a coloured fill.
  function inkOn(fill, dark, light) {
    const lf = luminance(fill);
    const contrast = (a, b) => (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05);
    return contrast(lf, luminance(dark)) >= contrast(lf, luminance(light)) ? dark : light;
  }

  /* ---------- Chart.js value-label plugin (end labels for single series, fitted labels inside stacks) ---------- */

  const valueLabels = {
    id: "valueLabels",
    afterDatasetsDraw(chart, _args, opts) {
      if (!opts || !opts.enabled) return;
      const { ctx } = chart;
      const horizontal = chart.options.indexAxis === "y";
      ctx.save();
      ctx.font = `500 12px ${opts.font}`;
      chart.data.datasets.forEach((ds, di) => {
        const meta = chart.getDatasetMeta(di);
        if (meta.hidden) return;
        meta.data.forEach((bar, i) => {
          const value = ds.data[i];
          if (value === null || value === undefined) return;
          const text = opts.format(value, i, di);
          const { x, y, base } = bar.getProps(["x", "y", "base"], true);
          if (opts.mode === "inside") {
            if (value === 0) return;
            const length = Math.abs(horizontal ? x - base : base - y);
            const thickness = horizontal ? bar.height : bar.width;
            if (length < ctx.measureText(text).width + 14 || thickness < 14) return; // never clip a label
            ctx.fillStyle = opts.insideInk[di];
            ctx.textAlign = "center";
            ctx.textBaseline = "middle";
            ctx.fillText(text, horizontal ? (x + base) / 2 : x, horizontal ? y : (y + base) / 2);
          } else {
            ctx.fillStyle = opts.color;
            if (horizontal) {
              ctx.textAlign = "left";
              ctx.textBaseline = "middle";
              ctx.fillText(text, x + 6, y);
            } else {
              ctx.textAlign = "center";
              ctx.textBaseline = "bottom";
              ctx.fillText(text, x, y - 5);
            }
          }
        });
      });
      ctx.restore();
    },
  };
  Chart.register(valueLabels);

  /* ---------- chart specs: each returns what to draw for the filtered rows ---------- */

  function rateSpec(rows, field, orderField, horizontal, sortDesc) {
    let table = M.segmentTable(rows, field, orderField);
    if (sortDesc) table = table.slice().sort((a, b) => b.churnRate - a.churnRate || b.customers - a.customers);
    const lead = M.leaders(table, "churnRate");
    let insight = "";
    if (lead && lead.value === 0) insight = "No churned customers in this selection.";
    else if (lead) {
      const detail = lead.segments.map((s) => `${s.churned} of ${s.customers}`).join("; ");
      insight = `Highest: ${listNames(lead.segments.map((s) => s.segment))} at ${fmt.pct(lead.value)} (${detail}).`;
    }
    return {
      horizontal,
      labels: table.map((s) => s.segment),
      series: [{ label: "Churn rate", data: table.map((s) => s.churnRate), color: "churned" }],
      valueFormat: fmt.pct,
      axisMax: 100,
      axisFormat: (v) => `${v}%`,
      endLabels: true,
      tooltipExtra: (i) => `${table[i].churned} of ${table[i].customers} customers churned`,
      insight,
      table: {
        head: [FIELD_LABELS[field], "Customers", "Churned", "Churn rate"],
        rows: table.map((s) => [s.segment, s.customers, s.churned, fmt.pct(s.churnRate)]),
      },
    };
  }

  function statusSpec(rows, field, orderField, percent) {
    const table = M.segmentTable(rows, field, orderField);
    const lead = M.leaders(table, "churnRate");
    let insight = "";
    if (lead && lead.value === 0) insight = "No churned customers in this selection.";
    else if (lead) {
      insight = `Most churn: ${listNames(lead.segments.map((s) => s.segment))}, ${lead.segments
        .map((s) => `${s.churned} of ${s.customers}`)
        .join("; ")} churned.`;
      const safest = table.filter((s) => s.churned === 0).map((s) => s.segment);
      if (safest.length) insight += ` No churn: ${listNames(safest)}.`;
    }
    const value = (s, key) => (percent ? (key === "churned" ? s.churnRate : s.retentionRate) : s[key]);
    return {
      horizontal: true,
      stacked: true,
      labels: table.map((s) => s.segment),
      series: [
        { label: "Churned", data: table.map((s) => value(s, "churned")), color: "churned" },
        { label: "Retained", data: table.map((s) => value(s, "active")), color: "retained" },
      ],
      valueFormat: percent ? fmt.pct : (v) => `${v} customers`,
      labelFormat: percent ? (v) => `${Math.round(v)}%` : (v) => String(v),
      axisMax: percent ? 100 : undefined,
      axisFormat: percent ? (v) => `${v}%` : (v) => (Number.isInteger(v) ? String(v) : ""),
      tooltipExtra: (i) => `${table[i].churned} churned · ${table[i].active} retained · ${table[i].customers} total`,
      insight,
      table: {
        head: [FIELD_LABELS[field], "Customers", "Churned", "Retained", "Churn rate"],
        rows: table.map((s) => [s.segment, s.customers, s.churned, s.active, fmt.pct(s.churnRate)]),
      },
    };
  }

  function revenueSplitSpec(rows) {
    const table = M.segmentTable(rows, "ContractType", "ContractOrder");
    const k = M.computeKpis(rows);
    const lead = M.leaders(table, "revenueAtRisk");
    let insight = "No revenue at risk in this selection.";
    if (lead && lead.value > 0) {
      insight = `${fmt.money(k.revenue_at_risk)} of ${fmt.money(k.monthly_revenue)} is at risk; ${listNames(
        lead.segments.map((s) => s.segment)
      )} carries ${fmt.money(lead.value)}.`;
    }
    return {
      horizontal: true,
      stacked: true,
      labels: table.map((s) => s.segment),
      series: [
        { label: "Revenue at risk", data: table.map((s) => s.revenueAtRisk), color: "churned" },
        { label: "Retained revenue", data: table.map((s) => s.retainedMrr), color: "retained" },
      ],
      valueFormat: fmt.money,
      labelFormat: fmt.money,
      axisFormat: (v) => inrWhole.format(v),
      tooltipExtra: (i) => `Monthly revenue: ${fmt.money(table[i].mrr)}`,
      insight,
      table: {
        head: ["Contract type", "Monthly revenue", "Retained", "At risk", "Share of revenue at risk"],
        rows: table.map((s) => [s.segment, fmt.money(s.mrr), fmt.money(s.retainedMrr), fmt.money(s.revenueAtRisk), fmt.pct(s.shareOfRevenueAtRisk)]),
      },
    };
  }

  function planSpec(rows) {
    const table = M.segmentTable(rows, "SubscriptionType", "MonthlyCharges");
    const price = (plan) => rows.find((r) => r.SubscriptionType === plan).MonthlyCharges;
    const k = M.computeKpis(rows);
    let insight = "";
    if (k.churned_customers && k.active_customers) {
      insight = `Churned customers paid ${fmt.money(k.avg_monthly_charge_churned)} a month on average; active customers ${fmt.money(k.avg_monthly_charge_active)}.`;
    } else if (k.total_customers) {
      insight = `Average monthly charge in this selection: ${fmt.money(k.arpu)}.`;
    }
    return {
      horizontal: false,
      stacked: true,
      labels: table.map((s) => [s.segment, inr.format(price(s.segment))]),
      series: [
        { label: "Churned", data: table.map((s) => s.churned), color: "churned" },
        { label: "Retained", data: table.map((s) => s.active), color: "retained" },
      ],
      valueFormat: (v) => `${v} customers`,
      labelFormat: (v) => String(v),
      axisFormat: (v) => (Number.isInteger(v) ? String(v) : ""),
      tooltipExtra: (i) => `${fmt.pct(table[i].churnRate)} churned · ${fmt.money(table[i].revenueAtRisk)} at risk`,
      insight,
      table: {
        head: ["Plan", "Monthly charge", "Customers", "Churned", "Churn rate", "Revenue at risk"],
        rows: table.map((s) => [s.segment, fmt.money(price(s.segment)), s.customers, s.churned, fmt.pct(s.churnRate), fmt.money(s.revenueAtRisk)]),
      },
    };
  }

  function riskBySpec(rows, field, orderField) {
    const table = M.segmentTable(rows, field, orderField);
    const lead = M.leaders(table, "revenueAtRisk");
    let insight = "No revenue at risk in this selection.";
    if (lead && lead.value > 0) {
      insight = `${listNames(lead.segments.map((s) => s.segment))}: ${fmt.money(lead.value)} (${fmt.pct(
        lead.segments[0].shareOfRevenueAtRisk
      )} of revenue at risk).`;
    }
    return {
      horizontal: false,
      labels: table.map((s) => s.segment),
      series: [{ label: "Revenue at risk", data: table.map((s) => s.revenueAtRisk), color: "churned" }],
      valueFormat: fmt.money,
      labelFormat: fmt.money,
      axisFormat: (v) => inrWhole.format(v),
      endLabels: true,
      tooltipExtra: (i) => `${fmt.pct(table[i].shareOfRevenueAtRisk)} of revenue at risk`,
      insight,
      table: {
        head: [FIELD_LABELS[field], "Customers", "Churned", "Revenue at risk", "Share"],
        rows: table.map((s) => [s.segment, s.customers, s.churned, fmt.money(s.revenueAtRisk), fmt.pct(s.shareOfRevenueAtRisk)]),
      },
    };
  }

  function arpuSpec(rows) {
    const table = M.segmentTable(rows, "ContractType", "ContractOrder");
    const lead = M.leaders(table, "arpu");
    const insight = lead ? `Highest: ${listNames(lead.segments.map((s) => s.segment))} at ${fmt.money(lead.value)} per customer per month.` : "";
    return {
      horizontal: true,
      labels: table.map((s) => s.segment),
      series: [{ label: "Avg revenue per customer", data: table.map((s) => s.arpu), color: "retained" }],
      valueFormat: fmt.money,
      labelFormat: fmt.money,
      axisFormat: (v) => inrWhole.format(v),
      endLabels: true,
      tooltipExtra: (i) => `${table[i].customers} customers · ${fmt.money(table[i].mrr)} monthly revenue`,
      insight,
      table: {
        head: ["Contract type", "Customers", "Monthly revenue", "Avg revenue per customer"],
        rows: table.map((s) => [s.segment, s.customers, fmt.money(s.mrr), fmt.money(s.arpu)]),
      },
    };
  }

  const CHARTS = {
    "ov-contract": { tab: "overview", spec: (r) => rateSpec(r, "ContractType", "ContractOrder", true, false) },
    "ch-status-contract": { tab: "churn", spec: (r) => statusSpec(r, "ContractType", "ContractOrder", false) },
    "ch-contract": { tab: "churn", spec: (r) => rateSpec(r, "ContractType", "ContractOrder", true, false) },
    "ch-tenure": { tab: "churn", spec: (r) => rateSpec(r, "TenureGroup", "TenureGroupOrder", false, false) },
    "ch-payment": { tab: "churn", spec: (r) => rateSpec(r, "PaymentMethod", null, true, true) },
    "rv-contract": { tab: "revenue", spec: revenueSplitSpec },
    "rv-plan": { tab: "revenue", spec: planSpec },
    "rv-tenure": { tab: "revenue", spec: (r) => riskBySpec(r, "TenureGroup", "TenureGroupOrder") },
    "rv-arpu": { tab: "revenue", spec: arpuSpec },
    "sg-tickets": { tab: "segments", spec: (r) => statusSpec(r, "SupportTicketBand", "SupportTicketBandOrder", true) },
    "sg-tenure": { tab: "segments", spec: (r) => statusSpec(r, "TenureGroup", "TenureGroupOrder", true) },
    "sg-payment": { tab: "segments", spec: (r) => statusSpec(r, "PaymentMethod", null, true) },
  };

  /* ---------- drawing ---------- */

  function ariaSummary(title, spec) {
    const parts = spec.labels.map((label, i) => {
      const name = Array.isArray(label) ? label.join(" ") : label;
      return `${name}: ${spec.series.map((s) => `${s.label} ${spec.valueFormat(s.data[i])}`).join(", ")}`;
    });
    return `${title}. ${parts.join("; ")}.`;
  }

  function buildTable(spec) {
    const head = `<thead><tr>${spec.table.head
      .map((h, i) => `<th scope="col"${i ? ' class="num"' : ""}>${h}</th>`)
      .join("")}</tr></thead>`;
    const body = spec.table.rows
      .map((r) => `<tr>${r.map((c, i) => (i ? `<td class="num">${c}</td>` : `<th scope="row">${c}</th>`)).join("")}</tr>`)
      .join("");
    return `<div class="table-scroll"><table class="data">${head}<tbody>${body}</tbody></table></div>`;
  }

  function drawChart(id, rows) {
    const card = document.querySelector(`[data-chart="${id}"]`);
    const box = card.querySelector(".chart-box");
    const canvas = document.getElementById(`c-${id}`);
    const insightEl = card.querySelector(`[data-insight="${id}"]`);
    let tableEl = card.querySelector(".chart-table");
    let emptyEl = card.querySelector(".chart-empty");
    if (!tableEl) {
      tableEl = document.createElement("div");
      tableEl.className = "chart-table";
      box.after(tableEl);
    }
    if (!emptyEl) {
      emptyEl = document.createElement("p");
      emptyEl.className = "chart-empty";
      emptyEl.textContent = "No customers match these filters.";
      box.after(emptyEl);
    }
    if (charts[id]) {
      charts[id].destroy();
      delete charts[id];
    }

    if (!rows.length) {
      box.hidden = true;
      tableEl.hidden = true;
      emptyEl.hidden = false;
      insightEl.textContent = "";
      return;
    }
    emptyEl.hidden = true;

    const spec = CHARTS[id].spec(rows);
    const title = card.querySelector("h2").textContent;
    insightEl.textContent = spec.insight;
    canvas.setAttribute("aria-label", ariaSummary(title, spec));

    const showTable = state.tableView.has(id);
    card.querySelector(".table-toggle").setAttribute("aria-pressed", String(showTable));
    tableEl.innerHTML = buildTable(spec);
    tableEl.hidden = !showTable;
    box.hidden = showTable;
    if (showTable) return;

    const p = palette();
    const font = { family: p.font, size: 12 };
    const darkInk = luminance(p.ink) < luminance(p.surface) ? p.ink : p.surface;
    const valueAxis = spec.horizontal ? "x" : "y";
    const categoryAxis = spec.horizontal ? "y" : "x";
    const gapBorder = spec.horizontal ? { left: 1, right: 1, top: 0, bottom: 0 } : { top: 1, bottom: 1, left: 0, right: 0 };

    charts[id] = new Chart(canvas, {
      type: "bar",
      data: {
        labels: spec.labels,
        datasets: spec.series.map((s) => ({
          label: s.label,
          data: s.data,
          backgroundColor: p[s.color],
          hoverBackgroundColor: p[s.color],
          borderColor: p.surface,
          borderWidth: spec.stacked ? gapBorder : 0,
          borderRadius: spec.stacked ? 0 : 4,
          borderSkipped: spec.stacked ? false : "start",
          maxBarThickness: 24,
          categoryPercentage: 0.72,
          barPercentage: 0.9,
        })),
      },
      options: {
        indexAxis: spec.horizontal ? "y" : "x",
        responsive: true,
        maintainAspectRatio: false,
        animation: reduceMotion ? false : { duration: 250 },
        layout: { padding: spec.endLabels ? (spec.horizontal ? { right: 64 } : { top: 22 }) : 4 },
        interaction: { mode: "index", axis: categoryAxis, intersect: false },
        scales: {
          [valueAxis]: {
            stacked: !!spec.stacked,
            beginAtZero: true,
            max: spec.axisMax,
            display: !spec.endLabels,
            grid: { color: p.line, drawTicks: false },
            border: { display: false },
            ticks: { color: p.muted, font, padding: 6, maxTicksLimit: 6, callback: (v) => spec.axisFormat(v) },
          },
          [categoryAxis]: {
            stacked: !!spec.stacked,
            grid: { display: false },
            border: { color: p.baseline },
            ticks: { color: p.ink2, font },
          },
        },
        plugins: {
          legend: {
            display: spec.series.length > 1,
            position: "top",
            align: "start",
            labels: { color: p.ink2, font, boxWidth: 10, boxHeight: 10, useBorderRadius: true, borderRadius: 3, padding: 14 },
          },
          tooltip: {
            backgroundColor: p.ink,
            titleColor: p.surface,
            bodyColor: p.surface,
            footerColor: p.surface,
            titleFont: { family: p.font, size: 12, weight: "600" },
            bodyFont: font,
            footerFont: { family: p.font, size: 11, weight: "400" },
            padding: 10,
            cornerRadius: 6,
            boxPadding: 4,
            callbacks: {
              title: (items) => {
                const label = items[0].label;
                return Array.isArray(label) ? label.join(" ") : label;
              },
              label: (ctx) => `${ctx.dataset.label}: ${spec.valueFormat(ctx.raw)}`,
              footer: (items) => (spec.tooltipExtra ? spec.tooltipExtra(items[0].dataIndex) : ""),
            },
          },
          valueLabels: {
            enabled: true,
            mode: spec.stacked ? "inside" : "end",
            font: p.font,
            color: p.ink2,
            insideInk: spec.series.map((s) => inkOn(p[s.color], darkInk, "#ffffff")),
            format: spec.labelFormat || spec.valueFormat,
          },
        },
      },
    });
  }

  /* ---------- KPI tiles and text ---------- */

  const NOTES = {
    customers: (k) => `${k.total_customers} of ${TOTAL} customers in view`,
    churn: (k) => (k.total_customers ? `${k.churned_customers} of ${k.total_customers} customers churned` : "No customers in view"),
    retention: (k) => (k.total_customers ? `${k.active_customers} of ${k.total_customers} customers active` : "No customers in view"),
    risk: (k) => (k.revenue_at_risk_pct === null ? "No revenue in view" : `${fmt.pct(k.revenue_at_risk_pct)} of monthly revenue`),
    riskAnnual: (k) => `About ${inrWhole.format(k.annualised_revenue_at_risk)} a year if not won back (× 12 estimate)`,
    tenure: (k) => `Churned ${fmt.dec1(k.avg_tenure_churned)} · active ${fmt.dec1(k.avg_tenure_active)} months`,
    active: () => "Customers with Churn = No",
    charges: (k) => `Avg charge: churned ${fmt.money(k.avg_monthly_charge_churned)} · active ${fmt.money(k.avg_monthly_charge_active)}`,
  };

  function renderKpis(k) {
    document.querySelectorAll("[data-kpi]").forEach((el) => {
      el.textContent = fmt[el.dataset.format](k[el.dataset.kpi]);
    });
    document.querySelectorAll("[data-note]").forEach((el) => {
      el.textContent = NOTES[el.dataset.note](k);
    });

    const churnShare = k.churn_rate_pct || 0;
    const retainShare = k.retention_rate_pct || 0;
    const segChurn = document.getElementById("split-churned");
    const segRetain = document.getElementById("split-retained");
    segChurn.style.flexBasis = `${churnShare}%`;
    segRetain.style.flexBasis = `${retainShare}%`;
    segChurn.hidden = churnShare === 0;
    segRetain.hidden = retainShare === 0;
    document.getElementById("split-churned-label").textContent = `${k.churned_customers} · ${fmt.pct(k.churn_rate_pct)}`;
    document.getElementById("split-retained-label").textContent = `${k.active_customers} · ${fmt.pct(k.retention_rate_pct)}`;
    document.getElementById("split").setAttribute(
      "aria-label",
      `Customer split: ${k.churned_customers} churned, ${k.active_customers} retained`
    );

    document.getElementById("health-summary").textContent = k.total_customers
      ? `Of ${k.total_customers} customers in view, ${k.churned_customers} churned (${fmt.pct(k.churn_rate_pct)}) and ${k.active_customers} are active. ` +
        `Revenue at risk is ${fmt.money(k.revenue_at_risk)} a month, ${fmt.pct(k.revenue_at_risk_pct)} of the ${fmt.money(k.monthly_revenue)} monthly revenue. ` +
        `Average tenure is ${fmt.dec1(k.avg_tenure_months)} months.`
      : "No customers match the current filters.";
  }

  /* ---------- segmentation tables ---------- */

  function renderSegmentTable(rows) {
    const field = state.segmentDim;
    const table = M.segmentTable(rows, field, SEGMENT_ORDER[field]);
    const head = ["Segment", "Customers", "Churned", "Churn rate", "Monthly revenue", "Revenue at risk", "Share of risk", "Avg tenure (months)"];
    const body = table
      .map(
        (s) => `<tr>
          <th scope="row">${s.segment}</th>
          <td class="num">${s.customers}</td>
          <td class="num">${s.churned}</td>
          <td class="num"><span class="rate-cell"><span class="rate-bar" aria-hidden="true"><span style="width:${s.churnRate}%"></span></span>${fmt.pct(s.churnRate)}</span></td>
          <td class="num">${fmt.money(s.mrr)}</td>
          <td class="num">${fmt.money(s.revenueAtRisk)}</td>
          <td class="num">${fmt.pct(s.shareOfRevenueAtRisk)}</td>
          <td class="num">${fmt.dec1(s.avgTenure)}</td>
        </tr>`
      )
      .join("");
    document.getElementById("segment-table").innerHTML =
      `<thead><tr>${head.map((h, i) => `<th scope="col"${i ? ' class="num"' : ""}>${h}</th>`).join("")}</tr></thead><tbody>${body}</tbody>`;

    const lead = M.leaders(table, "churnRate");
    const best = table.filter((s) => s.churned === 0).map((s) => s.segment);
    let text = "";
    if (lead && lead.value > 0) {
      text = `Highest churn: ${listNames(lead.segments.map((s) => s.segment))} (${fmt.pct(lead.value)}).`;
      if (best.length) text += ` Fully retained: ${listNames(best)}.`;
    } else if (lead) text = "No churned customers in this selection.";
    document.getElementById("segment-insight").textContent = text;
  }

  function renderMatrix(rows) {
    const contracts = M.options(ROWS, "ContractType", "ContractOrder");
    const methods = M.options(ROWS, "PaymentMethod", null);
    const head = `<thead><tr><th scope="col">Contract</th>${methods.map((m) => `<th scope="col" class="num">${m}</th>`).join("")}</tr></thead>`;
    const body = contracts
      .map((c) => {
        const cells = methods
          .map((m) => {
            const group = rows.filter((r) => r.ContractType === c && r.PaymentMethod === m);
            if (!group.length) return '<td class="na">–</td>';
            const k = M.computeKpis(group);
            return `<td class="num" style="--r:${k.churn_rate_pct / 100}">${fmt.pct(k.churn_rate_pct)} <span class="muted">· ${k.total_customers}</span></td>`;
          })
          .join("");
        return `<tr><th scope="row">${c}</th>${cells}</tr>`;
      })
      .join("");
    document.getElementById("matrix-table").innerHTML = head + `<tbody>${body}</tbody>`;
  }

  function renderCustomers(rows) {
    const sorted = rows.slice().sort((a, b) => b.ChurnFlag - a.ChurnFlag || a.TenureMonths - b.TenureMonths);
    const head = ["Customer", "Contract", "Tenure (months)", "Plan", "Monthly charge", "Support tickets", "Payment", "Status"];
    const body = sorted
      .map(
        (r) => `<tr>
          <th scope="row"><code>${r.CustomerID}</code></th>
          <td>${r.ContractType}</td>
          <td class="num">${r.TenureMonths}</td>
          <td>${r.SubscriptionType}</td>
          <td class="num">${fmt.money(r.MonthlyCharges)}</td>
          <td class="num">${r.SupportTickets}</td>
          <td>${r.PaymentMethod}</td>
          <td><span class="status"><i class="sw ${r.ChurnFlag ? "churned" : "retained"}" aria-hidden="true"></i>${r.ChurnStatus}</span></td>
        </tr>`
      )
      .join("");
    document.getElementById("customer-table").innerHTML =
      `<thead><tr>${head
        .map((h, i) => `<th scope="col"${[2, 4, 5].includes(i) ? ' class="num"' : ""}>${h}</th>`)
        .join("")}</tr></thead><tbody>${body}</tbody>`;
    document.getElementById("customer-count").textContent =
      `${rows.length} of ${TOTAL} customers, churned first, then by tenure. This is the table view of the data behind every chart.`;
  }

  /* ---------- orchestration ---------- */

  function currentRows() {
    return M.filterRows(ROWS, state.filters);
  }

  function renderTab(rows) {
    Object.entries(CHARTS).forEach(([id, def]) => {
      if (def.tab === state.tab) drawChart(id, rows);
    });
    if (state.tab === "segments") {
      renderSegmentTable(rows);
      renderMatrix(rows);
      renderCustomers(rows);
    }
  }

  function render() {
    const rows = currentRows();
    const k = M.computeKpis(rows);
    renderKpis(k);

    const active = FILTERS.filter((f) => state.filters[f.field] !== "All").map((f) => state.filters[f.field]);
    document.getElementById("filter-count").textContent =
      `Showing ${rows.length} of ${TOTAL} customers` + (active.length ? ` · ${active.join(" · ")}` : "");
    document.getElementById("empty-global").hidden = rows.length > 0 || state.tab === "insights";

    renderTab(rows);
  }

  function selectTab(tab, focus) {
    if (!TABS.includes(tab)) tab = "overview";
    state.tab = tab;
    TABS.forEach((t) => {
      const button = document.getElementById(`tab-${t}`);
      const selected = t === tab;
      button.setAttribute("aria-selected", String(selected));
      button.tabIndex = selected ? 0 : -1;
      document.getElementById(`panel-${t}`).hidden = !selected;
      if (selected && focus) button.focus();
    });
    try {
      history.replaceState(null, "", `#${tab}`);
    } catch (e) {
      /* hash updates are a convenience only */
    }
    render();
  }

  function resetFilters() {
    FILTERS.forEach((f) => {
      state.filters[f.field] = "All";
      document.getElementById(f.id).value = "All";
    });
    render();
  }

  function init() {
    FILTERS.forEach((f) => {
      const select = document.getElementById(f.id);
      M.options(ROWS, f.field, f.order).forEach((value) => select.add(new Option(value, value)));
      select.addEventListener("change", () => {
        state.filters[f.field] = select.value;
        render();
      });
    });
    document.getElementById("reset").addEventListener("click", resetFilters);
    document.getElementById("reset-2").addEventListener("click", resetFilters);

    document.getElementById("seg-dim").addEventListener("change", (e) => {
      state.segmentDim = e.target.value;
      renderSegmentTable(currentRows());
    });

    document.querySelectorAll(".tab").forEach((button) => {
      button.addEventListener("click", () => selectTab(button.dataset.tab));
      button.addEventListener("keydown", (e) => {
        const i = TABS.indexOf(state.tab);
        if (e.key === "ArrowRight") selectTab(TABS[(i + 1) % TABS.length], true);
        else if (e.key === "ArrowLeft") selectTab(TABS[(i - 1 + TABS.length) % TABS.length], true);
        else if (e.key === "Home") selectTab(TABS[0], true);
        else if (e.key === "End") selectTab(TABS[TABS.length - 1], true);
        else return;
        e.preventDefault();
      });
    });

    document.querySelectorAll("[data-chart]").forEach((card) => {
      const id = card.dataset.chart;
      card.querySelector(".table-toggle").addEventListener("click", () => {
        if (state.tableView.has(id)) state.tableView.delete(id);
        else state.tableView.add(id);
        drawChart(id, currentRows());
      });
    });

    // Repaint charts when the viewer's theme changes (OS setting or explicit toggle).
    window.matchMedia("(prefers-color-scheme: dark)").addEventListener("change", render);
    new MutationObserver(render).observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });

    window.addEventListener("hashchange", () => {
      const tab = location.hash.replace("#", "");
      if (TABS.includes(tab) && tab !== state.tab) selectTab(tab);
    });

    const fromHash = (location.hash || "").replace("#", "");
    selectTab(TABS.includes(fromHash) ? fromHash : "overview");
  }

  init();
})();
